// Model of a remote branch and the push rules.
const remote = { main: "c3" };      // server tip

function forcePush(branch, newTip) {
  remote[branch] = newTip;          // blindly overwrites
  return "ok";
}
// --force-with-lease: only push if the server tip is what I last saw.
function forceWithLease(branch, newTip, expected) {
  if (remote[branch] !== expected) {
    return `REFUSED (server has ${remote[branch]}, I expected ${expected})`;
  }
  remote[branch] = newTip;
  return "ok";
}

console.log("server main:", remote.main, "- I last fetched c3");
remote.main = "c4";                 // a teammate pushes c4 meanwhile
console.log("lease push:", forceWithLease("main", "x1", "c3"));
console.log("server main still:", remote.main);
console.log("plain force push:", forcePush("main", "x1"));
console.log("server main now:", remote.main, "(teammate's c4 lost)");

