# Semantic Versioning: bump MAJOR.MINOR.PATCH from commit types.
def bump(version, commits):
    major, minor, patch = map(int, version.split("."))
    level = "patch"
    for c in commits:
        if "!" in c.split(":")[0]:      # feat!: ... means breaking change
            level = "major"
        elif c.startswith("feat") and level != "major":
            level = "minor"
    if level == "major":
        return f"{major + 1}.0.0"       # reset lower numbers
    if level == "minor":
        return f"{major}.{minor + 1}.0"
    return f"{major}.{minor}.{patch + 1}"

start = "1.6.2"
cases = [
    ["fix: null check"],
    ["fix: null check", "feat: add export"],
    ["feat: add export", "feat!: drop v1 API"],
]
for commits in cases:
    print(start, commits, "->", bump(start, commits))
# Time O(n) for n commits, space O(1).
